output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "Customers are obliged to check out the entrance cart before doing their shopping.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "entrance_cart_available": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_available",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "Customers are prohibited from picking up shelf items unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart",
        "no_cart_in_use": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          "no_cart_in_use"
        ]
      }
    }
  },
  {
    "id": "must_return_cart_nw",
    "text": "After using a cart, customers are obliged to return it to the north-west cart return before leaving.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return": "at(0,1)",
        "cart_in_use": "hasCart",
        "cart_returned_nw": "cartAt(0,1)"
      },
      "events": {
        "return_cart_nw": {
          "pre": {
            "and": [
              "nw_cart_return",
              "cart_in_use",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_nw"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_in_use",
      "discharge": "return_cart_nw"
    }
  },
  {
    "id": "no_cart_exit",
    "text": "Customers are prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_use": "hasCart"
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "cart_in_use"
        ]
      }
    }
  },
  {
    "id": "leave_cart_only_at_return",
    "text": "Customers are prohibited from leaving a cart anywhere except the north-west cart return.",
    "abstraction": {
      "state_properties": {
        "nw_cart_return": "at(0,1)",
        "not_at_nw_cart_return": {
          "not": "nw_cart_return"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leave_cart",
          "not_at_nw_cart_return"
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "Customers are prohibited from exiting unless the cart has been parked at the north-west return bay.",
    "abstraction": {
      "state_properties": {
        "cart_returned_nw": "cartAt(0,1)",
        "cart_not_returned_nw": {
          "not": "cart_returned_nw"
        }
      },
      "events": {
        "exit_store": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "exit_store",
          "cart_not_returned_nw"
        ]
      }
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart is parked at the north-west return bay, customers are prohibited from doing further shopping interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_returned_nw": "cartAt(0,1)",
        "not_holding_cart": {
          "not": "hasCart"
        },
        "after_cart_return_phase": {
          "and": [
            "cart_returned_nw",
            "not_holding_cart"
          ]
        }
      },
      "events": {
        "shopping_interaction": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "EXIT"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "after_cart_return_phase",
          "shopping_interaction"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are prohibited from carrying goods by hand instead of using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_in_use": "hasCart",
        "hand_carrying_without_cart": {
          "and": [
            "carrying_by_hand",
            {
              "not": "cart_in_use"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "hand_carrying_without_cart"
    }
  }
]
